
/*!
 * FSC Login Bot — Boty animado para pantallas de login (Full Service & Clean)
 * Un solo archivo, sin dependencias ni framework. El robot va incluido (3 capas WebP en base64) y se anima en SVG
 * dentro de un Shadow DOM, así que no choca con los estilos de tu proyecto.
 *
 * USO
 *   <div id="robot"></div>
 *   <input id="user"> <input id="pass" type="password"> <button id="toggle">ver</button>
 *   <script src="fsc-login-bot.js"><\/script>
 *   <script>
 *     const bot = FSCLoginBot.mount('#robot', { username: '#user', password: '#pass', toggle: '#toggle' });
 *
 *     // en tu submit:
 *     bot.loading();                 // mientras verificas
 *     bot.success('Alexander');      // credenciales correctas
 *     bot.error('No coinciden.');    // credenciales incorrectas (vuelve solo a la normalidad)
 *   <\/script>
 *
 * QUÉ HACE SOLO
 *   · La cabeza y el emblema de la llave siguen el cursor; al escribir el usuario, siguen el cursor de texto.
 *   · En la contraseña el emblema cambia a un candado y agacha la cabeza (NO lee lo que escribís).
 *     Si mostrás la contraseña, mira para otro lado.
 *   · Avisa si está activado Bloq Mayús. Flota, mueve el brazo y pulsa con cada tecla.
 *   · Cargando: anillo giratorio · Éxito: check verde + pulgar arriba · Error: X roja, sacudida y brazo caído.
 *
 * OPCIONES: username, password, toggle (elemento o selector) · caption ('' = sin texto bajo el robot) · messages (textos propios)
 * API:      bot.say(texto, ms) · bot.wave() · bot.loading() · bot.success(nombre) · bot.error(texto) · bot.reset() · bot.destroy()
 */
(function () {
'use strict';
if (window.FSCLoginBot) return;

let uid = 0;

/* Capas del robot (recorte de tu render 3D): cuerpo, cabeza sin emblema y antebrazo con el pulgar. */
const IMG = {
    base: 'data:image/webp;base64,',
    head: 'data:image/webp;base64,',
    arm:  'data:image/webp;base64,'
};

const MESSAGES = {
    idle:    'Hola. Soy el guardián de este panel.',
    watch:   'Te escucho. Escribí tu usuario.',
    private: 'Me doy vuelta. No miro tu clave. 🔒',
    away:    'Miro para otro lado mientras la ves. 👀',
    loading: 'Verificando credenciales…',
    success: '¡Bienvenido! Abriendo el panel…',
    error:   'No coinciden. Probá de nuevo.',
    caps:    'Ojo: tenés Bloq Mayús activado.'
};

/* =====================================================================
   ESTILOS (dentro del Shadow DOM)
   ===================================================================== */
const CSS = `
:host { display: block; }
*, *::before, *::after { box-sizing: border-box; }
.wrap {
    --ring: #37b8ff; --glyph: #ffb347; --glow: #ff7a00;
    position: relative; width: 100%; max-width: 340px; margin: 0 auto;
    display: flex; flex-direction: column; align-items: center;
    font: 500 14px/1.3 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif; color: #f1f5ff;
    letter-spacing: normal; text-transform: none; text-align: center;
}
.wrap[data-mode="success"] { --ring: #3dffa0; --glyph: #8dffc2; --glow: #1fd67a; }
.wrap[data-mode="error"]   { --ring: #ff5c6c; --glyph: #ffa3ab; --glow: #ff3b4d; }
.wrap[data-mode="private"] { --ring: #4d86b8; --glyph: #a9c2e0; --glow: #4d86b8; }

.halo { position: absolute; left: 50%; top: 58%; width: 125%; aspect-ratio: 1; transform: translate(-50%, -50%); pointer-events: none;
    background: radial-gradient(circle, rgba(70,130,220,.20) 0%, rgba(210,120,50,.07) 45%, transparent 68%); }

.bubble {
    position: relative; z-index: 2; min-height: 42px; max-width: 100%; margin: 0 0 12px; padding: 10px 16px;
    display: flex; align-items: center; justify-content: center;
    border-radius: 12px; background: rgba(16, 24, 44, .94); border: 1px solid rgba(96, 128, 190, .3);
    box-shadow: 0 10px 28px rgba(0, 0, 0, .4); transition: opacity .12s ease, transform .12s ease;
}
.bubble::after {
    content: ''; position: absolute; left: 50%; bottom: -6px; width: 10px; height: 10px; margin-left: -5px;
    background: rgba(16, 24, 44, .94); border-right: 1px solid rgba(96, 128, 190, .3); border-bottom: 1px solid rgba(96, 128, 190, .3);
    transform: rotate(45deg);
}
.bubble.out { opacity: 0; transform: translateY(4px); }

.bot { position: relative; z-index: 1; display: block; width: 100%; max-width: 320px; height: auto; overflow: visible; }
.caption { position: relative; z-index: 1; margin-top: 8px; font-size: 11px; font-weight: 600; letter-spacing: .2em; color: #7385ab; }

/* Capas: flotar > modo (CSS) > agachar (CSS) > cabeza (JS) */
.g-float { animation: float 4.2s ease-in-out infinite; }
.g-mode  { transition: transform .3s ease; }
.g-bow, .g-lean { transform-origin: 200px 172px; }
.g-bow  { transition: transform .35s ease; }
.g-lean, .g-eyes { will-change: transform; }
.g-arm  { transform-origin: 343px 248px; transition: transform .35s ease; animation: armSway 5s ease-in-out infinite; }
.shadow { animation: shadowPulse 4.2s ease-in-out infinite; transform-origin: 228px 500px; }

/* Emblema (dibujado en vectores para poder cambiarlo de estado) */
.emb-glow { fill: var(--ring); opacity: .3; transform-box: fill-box; transform-origin: center; transition: opacity .1s, transform .1s, fill .2s; }
.wrap.tick .emb-glow { opacity: .85; transform: scale(1.12); }
.emb-ring  { fill: none; stroke: var(--ring); stroke-width: 6; transition: stroke .2s; }
.emb-ring2 { fill: none; stroke: var(--ring); stroke-width: 1.5; stroke-opacity: .5; transition: stroke .2s; }
.halo-use { fill: var(--glow); stroke: var(--glow); opacity: .9; }
.core-use { fill: var(--glyph); stroke: var(--glyph); }
.glyph { opacity: 0; transition: opacity .18s ease, transform .25s ease; transform-box: fill-box; transform-origin: center; }
.gl-wrench { opacity: 1; }
.wrap.blink .gl-wrench { opacity: .2; }
.spin-arc { fill: none; stroke: var(--ring); stroke-width: 4; stroke-linecap: round; stroke-dasharray: 60 300; opacity: 0; transform-box: fill-box; transform-origin: center; transition: opacity .2s; }

/* Modos */
.wrap[data-mode="private"] .gl-wrench, .wrap[data-mode="success"] .gl-wrench, .wrap[data-mode="error"] .gl-wrench { opacity: 0; }
.wrap[data-mode="private"] .gl-lock  { opacity: 1; }
.wrap[data-mode="success"] .gl-check { opacity: 1; }
.wrap[data-mode="error"]   .gl-cross { opacity: 1; }
.wrap[data-mode="private"] .g-bow { transform: rotate(-4deg) translateY(6px); }
.wrap[data-mode="private"] .emb-glow { opacity: .12; }

.wrap[data-mode="loading"] .spin-arc { opacity: 1; animation: spin .9s linear infinite; }
.wrap[data-mode="loading"] .gl-wrench { animation: pulse .55s ease-in-out infinite alternate; }

.wrap[data-mode="success"] .g-mode { animation: bob .9s ease both; }
.wrap[data-mode="success"] .g-arm { animation: thumbs .9s ease 1 both; }
.wrap[data-mode="success"] .emb-glow { opacity: .8; }

.wrap[data-mode="error"] .g-mode { animation: shake .5s ease both; }
.wrap[data-mode="error"] .g-arm { animation: none; transform: rotate(32deg); }
.wrap[data-mode="error"] .g-bow { transform: rotate(3deg) translateY(3px); }

.wrap.wave .g-arm { animation: armWave 1.3s ease-in-out both; }

@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
@keyframes shadowPulse { 0%, 100% { transform: scaleX(1); opacity: 1; } 50% { transform: scaleX(.9); opacity: .75; } }
@keyframes armSway { 0%, 100% { transform: rotate(-1.4deg); } 50% { transform: rotate(1.8deg); } }
@keyframes armWave { 0%, 100% { transform: rotate(0); } 20% { transform: rotate(-16deg); } 45% { transform: rotate(10deg); } 70% { transform: rotate(-14deg); } 90% { transform: rotate(6deg); } }
@keyframes thumbs { 0% { transform: rotate(0); } 30% { transform: rotate(-16deg); } 60% { transform: rotate(7deg); } 80% { transform: rotate(-6deg); } 100% { transform: rotate(0); } }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes pulse { from { opacity: 1; } to { opacity: .35; } }
@keyframes bob { 0%, 100% { transform: translateY(0); } 30% { transform: translateY(-14px); } 60% { transform: translateY(0); } 80% { transform: translateY(-5px); } }
@keyframes shake { 0%, 100% { transform: translateX(0); } 15% { transform: translateX(-9px); } 30% { transform: translateX(9px); } 45% { transform: translateX(-6px); } 60% { transform: translateX(6px); } 80% { transform: translateX(-3px); } }

@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation: none !important; transition: none !important; }
}
`;

/* =====================================================================
   SVG del robot: capas de imagen + emblema vectorial (sus ids se hacen únicos por instancia)
   ===================================================================== */
const svgMarkup = () => `
<svg class="bot" viewBox="18 6 416 516" aria-hidden="true" focusable="false">
  <defs>
    <filter id="BLUR" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="4"/></filter>
    <filter id="BLUR2" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="12"/></filter>
    <radialGradient id="DISC" cx="0.4" cy="0.32" r="0.85"><stop offset="0" stop-color="#2b71a6"/><stop offset=".6" stop-color="#173f6b"/><stop offset="1" stop-color="#0d2748"/></radialGradient>
    <g id="GWRENCH"><g transform="translate(-30 -30) scale(2.5)"><path stroke-width="1.6" stroke-linejoin="round" d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/></g></g>
    <g id="GLOCK"><rect x="-19" y="-3" width="38" height="28" rx="7" stroke-width="3"/><path fill="none" stroke-width="6" stroke-linecap="round" d="M-11 -5 V-14 a11 11 0 0 1 22 0 V-5"/><circle cx="0" cy="10" r="3.5" stroke-width="2"/></g>
    <g id="GCHECK"><path fill="none" stroke-width="9" stroke-linecap="round" stroke-linejoin="round" d="M-20 1 L-6 15 L21 -14"/></g>
    <g id="GCROSS"><path fill="none" stroke-width="9" stroke-linecap="round" d="M-16 -16 L16 16 M16 -16 L-16 16"/></g>
  </defs>

  <ellipse class="shadow" cx="228" cy="500" rx="122" ry="11" fill="#000" opacity=".5" filter="url(#BLUR)"/>

  <g class="g-float"><g class="g-mode">
    <g class="g-bow"><g class="g-lean">
      <image href="${IMG.head}" x="0" y="0" width="450" height="530"/>
      <g transform="translate(205 116)"><g class="g-eyes">
        <circle class="emb-glow" r="56" filter="url(#BLUR2)"/>
        <circle r="49" fill="url(#DISC)"/>
        <circle class="emb-ring" r="47"/>
        <circle class="emb-ring2" r="39"/>
        <circle class="spin-arc" r="56"/>
        <g class="glyph gl-wrench"><use class="halo-use" href="#GWRENCH" filter="url(#BLUR)"/><use class="core-use" href="#GWRENCH"/></g>
        <g class="glyph gl-lock"><use class="halo-use" href="#GLOCK" filter="url(#BLUR)"/><use class="core-use" href="#GLOCK"/></g>
        <g class="glyph gl-check"><use class="halo-use" href="#GCHECK" filter="url(#BLUR)"/><use class="core-use" href="#GCHECK"/></g>
        <g class="glyph gl-cross"><use class="halo-use" href="#GCROSS" filter="url(#BLUR)"/><use class="core-use" href="#GCROSS"/></g>
      </g></g>
    </g></g>
    <image href="${IMG.base}" x="0" y="0" width="450" height="530"/>
    <g class="g-arm"><image href="${IMG.arm}" x="0" y="0" width="450" height="530"/></g>
  </g></g>
</svg>`;

/* =====================================================================
   COMPONENTE
   ===================================================================== */
function mount(container, opts) {
    const $ = s => (typeof s === 'string' ? document.querySelector(s) : s) || null;
    container = $(container);
    if (!container) throw new Error('FSCLoginBot: no se encontró el contenedor');
    opts = Object.assign({ caption: '', messages: {} }, opts || {});
    const msg = Object.assign({}, MESSAGES, opts.messages);
    const userEl = $(opts.username), passEl = $(opts.password), toggleEl = $(opts.toggle);
    const reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

    /* ---- DOM ---- */
    const id = 'fscb' + (++uid);
    const host = document.createElement('div');
    container.appendChild(host);
    const sh = host.attachShadow({ mode: 'open' });
    const svg = svgMarkup().replace(/id="([A-Z0-9]+)"/g, 'id="' + id + '-$1"')
        .replace(/url\(#([A-Z0-9]+)\)/g, 'url(#' + id + '-$1)').replace(/href="#([A-Z0-9]+)"/g, 'href="#' + id + '-$1"');
    sh.innerHTML = '<style>' + CSS + '</style><div class="wrap" data-mode="idle"><div class="halo"></div>' +
        '<div class="bubble" role="presentation"><span class="bubble-text"></span></div>' + svg +
        (opts.caption ? '<div class="caption"></div>' : '') + '</div>';
    const wrap = sh.querySelector('.wrap'), bubble = sh.querySelector('.bubble'), bubbleText = sh.querySelector('.bubble-text');
    const emblem = sh.querySelector('.emb-ring'), leanG = sh.querySelector('.g-lean'), eyesG = sh.querySelector('.g-eyes');
    if (opts.caption) sh.querySelector('.caption').textContent = opts.caption;

    /* ---- Estado ---- */
    let lock = null;                 // 'loading' | 'success' | 'error'
    let override = null;             // texto temporal del globo
    let focus = null;                // 'user' | 'pass'
    let passVisible = !!(passEl && passEl.type === 'text');
    let caps = false;
    let pointer = null;
    let curMode = '', shownText = '';
    let msgTimer = 0, overrideTimer = 0, lockTimer = 0, renderTimer = 0, blinkTimer = 0, tickTimer = 0, waveTimer = 0, welcomeTimer = 0;
    const cleanups = [];
    const on = (t, ev, fn, o) => { if (!t) return; t.addEventListener(ev, fn, o); cleanups.push(() => t.removeEventListener(ev, fn, o)); };

    const mode = () => lock || (focus === 'pass' ? (passVisible ? 'away' : 'private') : focus === 'user' ? 'watch' : 'idle');

    /* ---- Globo de texto ---- */
    function setMessage(text) {
        if (text === shownText) return;
        shownText = text;
        clearTimeout(msgTimer);
        if (!bubbleText.textContent) { bubbleText.textContent = text; return; }
        bubble.classList.add('out');
        msgTimer = setTimeout(() => { bubbleText.textContent = shownText; bubble.classList.remove('out'); }, reduced ? 0 : 120);
    }

    /* ---- Mirada: cabeza y emblema se desplazan suavemente hacia un objetivo ---- */
    const MAXX = 15, MAXY = 9;
    const cur = { x: 0, y: 0, hx: 0, hy: 0, hr: 0 }, tgt = { x: 0, y: 0, hx: 0, hy: 0, hr: 0 };
    let raf = 0;

    function caretPoint(inp) {
        const r = inp.getBoundingClientRect();
        const max = inp.maxLength > 0 && inp.maxLength < 100 ? inp.maxLength : 24;
        const pos = inp.selectionStart == null ? inp.value.length : inp.selectionStart;
        const t = Math.min(1, pos / max);
        return { x: r.left + r.width * (0.1 + 0.8 * t), y: r.top + r.height / 2, t: t };
    }
    function retarget() {
        const m = mode();
        const r = emblem.getBoundingClientRect(), cx = r.left + r.width / 2, cy = r.top + r.height / 2;
        let px = null, py = null, prog = null;
        if (m === 'watch' && userEl) { const p = caretPoint(userEl); px = p.x; py = p.y; prog = p.t; }
        else if (m === 'away' && passEl) { const b = passEl.getBoundingClientRect(); px = cx - (b.left + b.width / 2 - cx); py = cy - (b.top + b.height / 2 - cy); }
        else if (m === 'idle' && pointer && !reduced) { px = pointer.x; py = pointer.y; }
        if (px === null) { tgt.x = tgt.y = tgt.hx = tgt.hy = tgt.hr = 0; }
        else {
            const dx = px - cx, dy = py - cy, dist = Math.hypot(dx, dy) || 1, f = Math.min(1, dist / 240);
            let nx = dx / dist * f;
            const ny = dy / dist * f;
            // Con el campo lejos y casi a la misma altura el ángulo apenas cambia: se exagera según el avance del texto
            if (prog !== null && Math.abs(nx) > 0.7) nx *= dx > 0 ? 0.45 + 0.55 * prog : 1 - 0.55 * prog;
            tgt.x = nx * MAXX; tgt.y = ny * MAXY; tgt.hx = nx * 6; tgt.hy = ny * 3.5; tgt.hr = nx * 3.5;
        }
        kick();
    }
    function tick() {
        raf = 0;
        const k = reduced ? 1 : 0.14;
        let delta = 0;
        for (const key in cur) { const d = tgt[key] - cur[key]; cur[key] += d * k; delta = Math.max(delta, Math.abs(d)); }
        eyesG.style.transform = 'translate(' + cur.x.toFixed(2) + 'px,' + cur.y.toFixed(2) + 'px)';
        leanG.style.transform = 'translate(' + cur.hx.toFixed(2) + 'px,' + cur.hy.toFixed(2) + 'px) rotate(' + cur.hr.toFixed(2) + 'deg)';
        if (delta > 0.02) raf = requestAnimationFrame(tick);
    }
    function kick() { if (!raf) raf = requestAnimationFrame(tick); }

    /* ---- Render ---- */
    function render() {
        const m = mode();
        if (m !== curMode) { curMode = m; wrap.setAttribute('data-mode', m); }
        setMessage(override || (caps && focus === 'pass' && !lock ? msg.caps : msg[m]));
        retarget();
    }
    function requestRender() { clearTimeout(renderTimer); renderTimer = setTimeout(render, 0); }

    /* ---- Efectos ---- */
    function wave() {
        if (reduced) return;
        wrap.classList.remove('wave'); void wrap.getBoundingClientRect(); wrap.classList.add('wave');
        clearTimeout(waveTimer); waveTimer = setTimeout(() => wrap.classList.remove('wave'), 1400);
    }
    function blinkLoop() {
        blinkTimer = setTimeout(() => {
            const m = mode();
            if (!reduced && (m === 'idle' || m === 'watch' || m === 'away')) {
                wrap.classList.add('blink');
                setTimeout(() => wrap.classList.remove('blink'), 130);
                if (Math.random() < 0.2) setTimeout(() => { wrap.classList.add('blink'); setTimeout(() => wrap.classList.remove('blink'), 110); }, 260);
            }
            blinkLoop();
        }, 2600 + Math.random() * 3000);
    }
    function typingFx() {
        wrap.classList.add('tick');
        clearTimeout(tickTimer);
        tickTimer = setTimeout(() => wrap.classList.remove('tick'), 110);
        retarget();
    }
    function capsCheck(e) {
        const c = !!(e.getModifierState && e.getModifierState('CapsLock'));
        if (c !== caps) { caps = c; requestRender(); }
    }

    /* ---- Eventos ---- */
    if (userEl) {
        on(userEl, 'focus', () => { focus = 'user'; requestRender(); });
        on(userEl, 'blur', () => { if (focus === 'user') focus = null; requestRender(); });
        ['input', 'keyup', 'click', 'select'].forEach(ev => on(userEl, ev, typingFx));
    }
    if (passEl) {
        on(passEl, 'focus', () => { focus = 'pass'; requestRender(); });
        on(passEl, 'blur', () => { if (focus === 'pass') focus = null; caps = false; requestRender(); });
        on(passEl, 'keydown', capsCheck);
        on(passEl, 'keyup', capsCheck);
        on(passEl, 'input', typingFx);
        if (window.MutationObserver) {                 // detecta el cambio password <-> text sin importar cómo lo haga tu página
            const mo = new MutationObserver(() => { const v = passEl.type === 'text'; if (v !== passVisible) { passVisible = v; requestRender(); } });
            mo.observe(passEl, { attributes: true, attributeFilter: ['type'] });
            cleanups.push(() => mo.disconnect());
        }
    }
    if (toggleEl) {                                    // el botón del ojito cuenta como "estar en la contraseña"
        on(toggleEl, 'focus', () => { focus = 'pass'; requestRender(); });
        on(toggleEl, 'blur', () => { if (focus === 'pass' && document.activeElement !== passEl) focus = null; requestRender(); });
    }
    on(window, 'pointermove', e => { pointer = { x: e.clientX, y: e.clientY }; if (mode() === 'idle') retarget(); }, { passive: true });
    on(document.documentElement, 'pointerleave', () => { pointer = null; retarget(); });
    on(window, 'resize', retarget);
    on(window, 'scroll', retarget, { passive: true, capture: true });

    if (document.activeElement === userEl) focus = 'user';
    if (document.activeElement === passEl) focus = 'pass';
    render();
    blinkLoop();
    welcomeTimer = setTimeout(wave, 700);              // saludo inicial con el brazo

    /* ---- API pública ---- */
    return {
        say(text, ms) {
            clearTimeout(overrideTimer);
            override = String(text);
            render();
            overrideTimer = setTimeout(() => { override = null; render(); }, ms || 3200);
        },
        wave,
        loading() { clearTimeout(lockTimer); clearTimeout(overrideTimer); override = null; lock = 'loading'; render(); },
        success(name) {
            clearTimeout(lockTimer); clearTimeout(overrideTimer);
            lock = 'success'; override = name ? '¡Bienvenido, ' + name + '!' : msg.success; render();
        },
        error(text) {
            clearTimeout(lockTimer); clearTimeout(overrideTimer);
            lock = 'error'; override = text || msg.error; render();
            lockTimer = setTimeout(() => { lock = null; override = null; render(); }, 3000);
        },
        reset() { clearTimeout(lockTimer); clearTimeout(overrideTimer); lock = null; override = null; render(); },
        get mode() { return curMode; },
        destroy() {
            [blinkTimer, msgTimer, overrideTimer, lockTimer, renderTimer, tickTimer, waveTimer, welcomeTimer].forEach(clearTimeout);
            cancelAnimationFrame(raf); cleanups.forEach(fn => fn()); host.remove();
        }
    };
}

window.FSCLoginBot = { mount };
})();

